// Deposited granular column of the crumbling regime: the target implementation of the formal definition
// (the formal definition of the grains released at rest, Appendix A of the paper).
//
// The column is an initial condition, generated by a fixed procedure from the run's seed, so that every engine
// and every refinement level starts from the same column (as the break-up state of the rigid regime is analytic):
//   1. loose angular grains (irregular hexagons, leaves.js grainsInRegion, cell size d) fill the box of width t
//      between the backstop (x = -t) and a temporary gate (x = 0), from the base (ground, or top of the residual
//      wall) up to a generation height K * Hr;
//   2. they settle under gravity in planck.js at fixed settings (DEPOSITION below), frictionless (grain-grain,
//      grain-walls and grain-base) and with light linear damping, to a dense packing;
//   3. the column is levelled: grains whose centroid lies above h0 + Hr are removed (their number is reported);
//      if the settled column does not reach h0 + Hr, steps 1-2 are repeated with K x 1.25;
//   4. the grain density is rho / phi_s, with phi_s = (sum of grain areas) / (t Hr), so that the column mass equals
//      the wall mass rho t Hr; velocities are set to 0.
// Release (gate removal at time 0) is the start of the run: the run's scene has no gate.
// Optional uniform gap g (leaves.gap): after levelling, every grain is shrunk about its
// centroid so that each edge moves inwards by at least g/2 (clear distance >= g between touching grains); mass and
// centroid are unchanged, inertia scales with the square of the shrink factor.
// Columns are cached on disk by a hash of their inputs (the procedure is deterministic; the cache saves time only).
'use strict';
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { grainsInRegion } = require('./leaves');
const { kinematics, makeStopper } = require('./stop');

const VERSION = 'column-1';
// fixed generator settings: planck.js level 0 step and iterations, linear damping 2 1/s during the deposition only
// (frictionless grains otherwise keep sloshing; chosen on 2026-10-17 on columns outside the sample, from time to rest only)
const DEPOSITION = { dt: 1 / 480, velocityIterations: 60, positionIterations: 30, linearSlop: 0.0005, airDrag: 2,
                     K0: 2.0, Kgrow: 1.25, maxTries: 4,
                     stop: { checkEvery: 0.05, keRel: 1e-6, vMax: 0.01, hold: 0.25, tCap: 30 } };
const CACHE = process.env.FACADE_COLUMN_CACHE || path.join(require('os').tmpdir(), 'facade-debris-column-cache');

function columnKey(P, geom) {
  return crypto.createHash('sha1').update(JSON.stringify({ v: VERSION, t: P.t, Hr: P.Hr, h0: geom.h0, d: P.leaves.grain, rho: P.rho, e: P.e,
    seed: P.variability.seed, dep: DEPOSITION })).digest('hex');
}

async function deposit(P, geom, rng) {
  const { createPlanckEngine } = require('../engines/planck_engine');
  const t = P.t, h0 = geom.h0, Hr = P.Hr, d = P.leaves.grain;
  let K = DEPOSITION.K0, tries = 0;
  for (;;) {
    tries++;
    const Hgen = K * Hr;
    const grains = grainsInRegion(P, -t, t, h0, Hgen, d, rng, 0);
    const top = h0 + Hgen + 2;
    const statics = [
      { id: 'base', shape: { type: 'segment', x0: -t - 1, y0: h0, x1: 1, y1: h0 }, x: 0, y: 0, phi: 0, material: 'ground' },
      { id: 'backstop', shape: { type: 'box', w: 0.3, h: top - h0 }, x: -t - 0.15, y: (h0 + top) / 2, phi: 0, material: 'masonry' },
      { id: 'gate', shape: { type: 'box', w: 0.3, h: top - h0 }, x: 0.15, y: (h0 + top) / 2, phi: 0, material: 'masonry' },
    ];
    const scene = { gravity: [0, -9.81], dt: DEPOSITION.dt, airDrag: DEPOSITION.airDrag,
      contactRules: { 'masonry|masonry': { mu: 0, e: P.e }, 'ground|masonry': { mu: 0, e: P.e } }, statics,
      bodies: grains.map(b => ({ id: b.id, shape: { type: 'polygon', vertices: b.vertices, mass: b.mass, inertia: b.inertia },
                                 x: b.x, y: b.y, phi: 0, vx: 0, vy: 0, omega: 0, density: b.density, material: 'masonry' })) };
    const eng = createPlanckEngine({ linearSlop: DEPOSITION.linearSlop, velocityIterations: DEPOSITION.velocityIterations,
                                     positionIterations: DEPOSITION.positionIterations });
    await eng.init(scene);
    const M = grains.reduce((s, b) => s + b.mass, 0);
    const stopper = makeStopper(DEPOSITION.stop, M * 9.81 * Hgen / 2);
    const nCheck = Math.round(DEPOSITION.stop.checkEvery / DEPOSITION.dt);
    let tNow = 0, steps = 0, res, states;
    for (;;) {
      await eng.advance(nCheck); steps += nCheck; tNow = steps * DEPOSITION.dt;
      states = await eng.state();
      res = stopper(tNow, kinematics(grains, states));
      if (res.stop) break;
    }
    await eng.dispose();
    const byId = new Map(states.map(s => [s.id, s]));
    const yMax = Math.max(...states.map(s => s.y));
    if (yMax < h0 + Hr && tries < DEPOSITION.maxTries) { K *= DEPOSITION.Kgrow; continue; }
    const kept = grains.filter(b => byId.get(b.id).y <= h0 + Hr);
    const area = kept.reduce((s, b) => s + b.mass / b.density, 0);
    const phiS = area / (t * Math.min(Hr, yMax - h0));
    return {
      grains: kept.map((b, i) => { const s = byId.get(b.id); return { vertices: b.vertices, x: s.x, y: s.y, phi: s.phi, area: b.mass / b.density, J: b.inertia / b.density }; }),
      info: { version: VERSION, nGenerated: grains.length, nKept: kept.length, nRemoved: grains.length - kept.length, phiS, K, tries,
              tDeposit: tNow, depositStop: res.reason, reachedHr: yMax >= h0 + Hr },
    };
  }
}

async function depositedColumn(P, geom, rng) {
  const key = columnKey(P, geom), f = path.join(CACHE, key + '.json');
  let col = null;
  if (fs.existsSync(f)) { try { col = JSON.parse(fs.readFileSync(f, 'utf8')); } catch (e) { col = null; } }
  if (!col) {
    col = await deposit(P, geom, rng);
    fs.mkdirSync(CACHE, { recursive: true });
    const tmp = f + '.' + process.pid + '.' + Math.random().toString(36).slice(2) + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(col)); fs.renameSync(tmp, f);
  }
  const rhoG = P.rho / col.info.phiS, g = (P.leaves && P.leaves.gap) || 0;
  const grains = col.grains.map((c, i) => {
    let V = c.vertices, k = 1;
    if (g) {
      let a = Infinity;                                   // smallest distance from the centroid to an edge line
      for (let j = 0; j < V.length; j++) {
        const [x0, y0] = V[j], [x1, y1] = V[(j + 1) % V.length];
        a = Math.min(a, Math.abs(x0 * y1 - x1 * y0) / Math.hypot(x1 - x0, y1 - y0));
      }
      k = 1 - (g / 2) / a;
      V = V.map(([x, y]) => [k * x, k * y]);
    }
    const mass = rhoG * c.area, R = Math.max(...V.map(([x, y]) => Math.hypot(x, y)));
    return { id: i, layer: null, col: null, type: 'grain', shape: 'polygon', vertices: V, w: 2 * R, h: 2 * R,
             x: c.x, y: c.y, phi: c.phi, vx: 0, vy: 0, omega: 0, density: mass / (c.area * k * k), material: 'masonry',
             mass, inertia: rhoG * c.J * k * k };
  });
  return { grains, info: Object.assign({}, col.info, { rhoGrain: rhoG, gap: g, key }) };
}

module.exports = { depositedColumn, deposit, DEPOSITION, VERSION };
